async function main() {
  console.log('Imperialpedia content rewrite publish');
  console.log(`  target : ${TARGET_BASE}`);
  console.log(`  mode   : ${DRY_RUN ? 'DRY RUN' : 'UPDATE'}\n`);

  if (!DRY_RUN && !TOKEN) throw new Error('No CMS_TOKEN set — provide a prod super_admin bearer to update.');

  for (const rewrite of REWRITES) {
    const article = await findBySlug(rewrite.slug);
    if (!article) {
      console.log(`  ! not found: ${rewrite.slug} — skipped`);
      continue;
    }

    if (DRY_RUN) {
      console.log(`  ~ would rewrite ${rewrite.slug}  (${rewrite.body.length} chars, ${rewrite.citations.length} citations)`);
      continue;
    }

    const nextCustomFields = { ...(article.customFields || {}), citations: rewrite.citations };
    await adminApi('PATCH', `/cms/websites/${encodeURIComponent(SITE)}/content/${article.id}`, {
      contentBlocks: [{ id: 'blk-rewrite-0', type: 'html', order: 0, content: { html: rewrite.body } }],
      customFields: nextCustomFields,
    });
    console.log(`  ✓ rewrote ${rewrite.slug}`);
  }

  console.log(DRY_RUN ? '\n(dry run — nothing was updated)' : '\n✓ complete.');
}

main().catch((e) => { console.error('\n✗ FATAL:', e.message); process.exit(1); });
